                rhs.head.magic_trailing_comma is None
            )
            if (
                not (
                    is_split_right_after_equal
                    and rhs_head_contains_brackets
                    and rhs_head_short_enough
                    and rhs_head_explode_blocked_by_magic_trailing_comma
                )
